ono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":8},{"nombre":"丁尼","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":67500}]},{"desde":9,"hasta":10,"creditos":0,"materiales":[{"nombre":"特化电击芯片","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":10},{"nombre":"丁尼","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":90000}]},{"desde":10,"hasta":11,"creditos":0,"materiales":[{"nombre":"特化电击芯片","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":12},{"nombre":"丁尼","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":112500}]},{"desde":11,"hasta":12,"creditos":0,"materiales":[{"nombre":"「仓鼠笼」访问器","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/07/19/11038150/792f4cd5ae09d68be7102cf6eb763e1a_7199202031553309278.png","cantidad":1},{"nombre":"特化电击芯片","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":15},{"nombre":"丁尼","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":135000}]}]}'::jsonb, '[{"nivel":1,"nombre":"«Determinación indómita»","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/6335146d351f78f0a628618f2a849181_3119698053713316104.png","efecto":"El número máximo de cargas de prisión electrógena que aplica el ataque normal: Saetas primordiales aumenta a 14. Al activar un receptáculo voltaico, dispara 2 Saetas primordiales consecutivas contra el objetivo.","cita":"«No soy como esos tercos que solo quieren enfrentarse al enemigo de frente. Ya sea un ataque directo o uno por la espalda, cualquier ofensiva que me ayude a salir del trabajo antes es bienvenida.»"},{"nivel":2,"nombre":"Languideza","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/469f9554aa138a057dacb98ede59a6d3_8037901845155267600.png","efecto":"Al ejecutar la técnica en cadena o la técnica definitiva, Harumasa obtiene 7 cargas de bombardeo electromagnético. Pueden acumularse hasta 7 cargas.\nAl contar con bombardeo electromagnético, el daño infligido por el ataque rápido: Cuerda célica - Corte aumenta en un 50 %. Tras ejecutar el ataque rápido: Cuerda célica - Corte, consume 1 carga de bombardeo electromagnético.","cita":"«No me mires así. En realidad soy muy débil, ¿sabes?»\nHarumasa se recuesta sobre la mesa con actitud perezosa.\n«¿Qué tal si buscas a otra persona para que se encargue de la operación?»"},{"nivel":3,"nombre":"Mentira piadosa","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/28f2d7ccb68295e6b2c99fb99b577db4_8003165392045521961.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"«No te preocupes, este no será mi final.»\nSe enjuga la sangre que le cae de las comisuras de los labios con una sonrisa y vuelve a tensar la cuerda de su arco.\n«Después de todo, pienso vivir el tiempo suficiente para convertirme en un problema para todos.»"},{"nivel":4,"nombre":"Motivación intermitente","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/fc5c9f6a7297408a0823e8ff2d31f79e_3427042453878724993.png","efecto":"La duración del efecto de prisión electrógena aumenta a 20 s. Al golpear a un enemigo con el ataque rápido: Cuerda célica - Corte, Harumasa obtiene 30 dB. Puede activarse un máximo de una vez por cada habilidad. Al ejecutar la técnica definitiva, aplica sobre todos los enemigos en el campo de batalla el número máximo de cargas de prisión electrógena.","cita":"En contadas ocasiones, Harumasa se siente motivado y lleno de energía... Normalmente, ocurre durante los últimos cinco minutos de la jornada de trabajo."},{"nivel":5,"nombre":"Ignoto","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/ada22c7100cfcd504dc951c773bb06b8_8375432747173267291.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"«Quiero vacaciones, libertad, ¡quiero ser feliz todos los días!»\n«Es broma. Quiero vivir.»"},{"nivel":6,"nombre":"Entendimiento tácito","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/cc8354becbb5422d928dcc39ba6df7fa_4143672430113157989.png","efecto":"Al golpear a un enemigo afectado por Aturdimiento o una Anomalía de Atributo con Saetas primordiales, Harumasa ignora un 15 % de la resistencia eléctrica del objetivo durante 12 s. Al golpear 12 veces al mismo enemigo con Saetas primordiales, se genera una explosión electromagnética adicional, infligiendo daño eléctrico equivalente a un 1500 % del Ataque de Harumasa al objetivo.","cita":"«Mi maestro me enseñó muchas cosas, como a disparar con el arco, manejar la espada y sobrevivir en este mundo con mi cuerpo.»\n«¿Y qué pasó después?»\n«Pues... que me abandonó.»"}]'::jsonb, null, null),
  ('zzz-miyabi', '[{"campo":"Sexo","valor":"Femenino"},{"campo":"Afiliación","valor":"División N.6"},{"campo":"Estatura","valor":"170 cm (Incluyendo las orejas)"},{"campo":"Cumpleaños","valor":"19 de Junio"},{"campo":"VA (CHS)","valor":"Ruan Congqing (阮从青)"},{"campo":"VA (JP)","valor":"Ami Koshimizu (小清水亜美)"},{"campo":"VA (KO)","valor":"Kim Do-hee (김도희)"},{"campo":"VA (EN)","valor":"Cristina Vee"},{"campo":"Versión de lanzamiento","valor":"1.4"},{"campo":"Amplificador exclusivo","valor":"Templo a la granizada estelífera"},{"campo":"Afiliación común","valor":"Soukaku, Tsukishiro Yanagi, Asaba Harumasa, Agente Gulliver"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Hálitos de la nevisca","descripcion":"Pulsa para usarlo.\nEjecuta hasta 5 cortes hacia delante.\nLos dos primeros cortes infligen daño físico y los tres últimos infligen daño gélido.\nDurante el quinto corte del ataque normal, puede bloquear los ataques enemigos."},{"nombre":"Ataque normal: Estación de la escarcha","descripcion":"Al contar con 2 o más cargas de cencellada, mantén pulsado para usarlo.\nHoshimi Miyabi envaina su espada, adoptando la posición de estación de la escarcha, y comienza a acumular fuerza. Por cada nivel de fuerza que acumule, consume 2 cargas de cencellada hasta un máximo de 3 niveles de fuerza.\nAl soltar o consumir todas las cargas de cencellada, Hoshimi Miyabi desenvaina su hoja y ejecuta un poderoso corte hacia delante, infligiendo una gran cantidad de daño gélido en función de la fuerza acumulada. A continuación, abandona la posición de estación de la escarcha.\nMientras Miyabi está en la posición de estación de la escarcha, la agente se vuelve invulnerable. Hoshimi Miyabi puede tener hasta 6 cargas de cencellada. Al entrar en combate, Miyabi obtiene inmediatamente 3 cargas de cencellada."}]