uego, la agente se vuelve invulnerable."}],"atributos":[{"clave":"Técnica especial: Maduración comburente","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño","valores":["57.8%","63.1%","68.4%","73.7%","79%","84.3%","89.6%","94.9%","100.2%","105.5%","110.8%","116.1%","121.4%","126.7%","132%","137.3%"]},{"clave":"Multiplicador de daño de ataque cargado","valores":["62.4%","68.1%","73.8%","79.5%","85.2%","90.9%","96.6%","102.3%","108%","113.7%","119.4%","125.1%","130.8%","136.5%","142.2%","147.9%"]},{"clave":"Multiplicador de Aturdimiento","valores":["57.8%","60.5%","63.2%","65.9%","68.6%","71.3%","74%","76.7%","79.4%","82.1%","84.8%","87.5%","90.2%","92.9%","95.6%","98.3%"]},{"clave":"Multiplicador de Aturdimiento de ataque cargado","valores":["62.4%","65.3%","68.2%","71.1%","74%","76.9%","79.8%","82.7%","85.6%","88.5%","91.4%","94.3%","97.2%","100.1%","103%","105.9%"]},{"clave":"","valores":["","","","","","","","","","","","","","","",""]},{"clave":"Técnica especial EX: Agitado comburente","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de torrente continuo","valores":["543.8%","593.3%","642.8%","692.3%","741.8%","791.3%","840.8%","890.3%","939.8%","989.3%","1038.8%","1088.3%","1137.8%","1187.3%","1236.8%","1286.3%"]},{"clave":"Multiplicador de Aturdimiento de torrente continuo","valores":["378.6%","395.9%","413.2%","430.5%","447.8%","465.1%","482.4%","499.7%","517%","534.3%","551.6%","568.9%","586.2%","603.5%","620.8%","638.1%"]},{"clave":"Multiplicador de daño de estallido de fuego","valores":["96.7%","105.5%","114.3%","123.1%","131.9%","140.7%","149.5%","158.3%","167.1%","175.9%","184.7%","193.5%","202.3%","211.1%","219.9%","228.7%"]},{"clave"